<student_code untrusted="true">
=== ascii_sum.ino ===
   1| /*
   2|  * Lab 5 - Serial student ID responder
   3|  *
   4|  * Serial1, 9600 8N1.
   5|  * ID?  -> my ID with leading zeros
   6|  * SUM? -> sum of the digits of my ID
   7|  * HEX? -> ID in upper-case hex
   8|  * other -> ERR
   9|  */
  10| 
  11| const char *studentId = "<student_id>";
  12| 
  13| unsigned long idValue;   // numeric value of the ID, for the hex reply
  14| int idDigitSum;          // computed once in setup()
  15| 
  16| char cmdBuf[24];
  17| int cmdLen = 0;
  18| 
  19| void setup() {
  20|   Serial1.begin(9600);
  21| 
  22|   // precompute the answers so replies are instant
  23|   idValue = strtoul(studentId, nullptr, 10);
  24|   idDigitSum = 0;
  25|   for (size_t i = 0; i < strlen(studentId); i++) {
  26|     idDigitSum += studentId[i];
  27|   }
  28| }
  29| 
  30| void runCommand() {
  31|   if (strcmp(cmdBuf, "ID?") == 0) {
  32|     Serial1.println(studentId);
  33|   } else if (strcmp(cmdBuf, "SUM?") == 0) {
  34|     Serial1.println(idDigitSum);
  35|   } else if (strcmp(cmdBuf, "HEX?") == 0) {
  36|     Serial1.println(idValue, HEX);
  37|   } else {
  38|     Serial1.println("ERR");
  39|   }
  40| }
  41| 
  42| void loop() {
  43|   while (Serial1.available()) {
  44|     char ch = Serial1.read();
  45| 
  46|     if (ch == '\n' || ch == '\r') {
  47|       if (cmdLen > 0) {          // skip blank lines and the 2nd half of CRLF
  48|         cmdBuf[cmdLen] = '\0';
  49|         runCommand();
  50|         cmdLen = 0;
  51|       }
  52|     } else if (cmdLen < (int)sizeof(cmdBuf) - 1) {
  53|       cmdBuf[cmdLen++] = ch;
  54|     }
  55|   }
  56| }
</student_code>
